"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73647"],{91612(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.tipo_banca_nao_encontrado","status":422,"titulo":"O tipo de banca n\xe3o existe ou est\xe1 desativado"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.tipo_banca_nao_encontrado","requisitos":[],"oQueAconteceu":["A fase do cronograma declara as bancas que atuam nela (`bancasRequeridas`), e\\ncada banca \xe9 de um tipo do cadastro do m\xf3dulo Configura\xe7\xe3o. O pedido de defini\xe7\xe3o\\ndo cronograma (`PUT .../cronograma-fases`) citou, em\\n`fases[n].bancasRequeridas[m].tipoBancaId`, um identificador que n\xe3o corresponde a\\nnenhum tipo de banca, ou que corresponde a um tipo desativado no cadastro. A mensagem da\\nresposta diz: \\"O tipo de banca indicado n\xe3o existe ou est\xe1 desativado no cadastro.\\" Ela n\xe3o\\nrepete o identificador enviado.","O tipo de banca \xe9 copiado por valor para o cronograma, e sem ele a banca n\xe3o pode\\nser montada. A confer\xeancia segue pelas demais recusas da mesma banca (candidatos atendidos, regra de\\ndelibera\xe7\xe3o e consequ\xeancia da aus\xeancia) e pelas demais bancas da mesma fase, e as recusas\\ndelas se somam a esta no array `errors[]`; s\xf3 a verifica\xe7\xe3o que depende do tipo, como a\\nconsequ\xeancia da aus\xeancia exigir banca que avalia o m\xe9rito, n\xe3o \xe9 feita. Em seguida a **montagem do cronograma\\n\xe9 interrompida** nessa fase: as fases anteriores da lista, com as viola\xe7\xf5es que j\xe1\\ntiveram, saem na mesma resposta, e as seguintes n\xe3o chegam a ser conferidas. Nada\\n\xe9 gravado."],"comoResolver":["Confira, no cadastro de tipos de banca do m\xf3dulo Configura\xe7\xe3o, o identificador do\\ntipo pretendido e use-o em `tipoBancaId`. Se o tipo foi desativado no cadastro e\\nainda deve existir, pe\xe7a a quem o gere que o restabele\xe7a antes de repetir a\\ndefini\xe7\xe3o do cronograma. Corrija tamb\xe9m as demais viola\xe7\xf5es que a resposta trouxer."],"ondeAparece":["- Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);